import React from 'react';
import { useHistory } from 'react-router-dom';
import { PRODUCT_ROUTE } from '../utils/const';
import { observer } from 'mobx-react-lite';
import '../css/components/ProductItem.css';

const ProductItem = ({ product }) => {
    const history = useHistory();

    if (!product) {
        return null; 
    }

    return (
        <div className="product-item" onClick={() => history.push(PRODUCT_ROUTE + '/' + product.id)}>
            <div className="product-image-container">
                <img 
                    src={process.env.REACT_APP_API_URL + product.img} 
                    alt={product.name}
                    className="product-image"
                    onError={(e) => {
                        e.target.src = '/placeholder-image.jpg';
                    }}
                />
                <div className="product-badge">Новинка</div>
            </div>
            <div className="product-content">
                <h3 className="product-name">{product.name || 'Без названия'}</h3>
                <div className="product-details">
                    <div className="product-city">{product.city || 'Город не указан'}</div>
                    <div className="product-price">{product.price || '0'} ₽</div>
                </div>
                <button className="product-button">Посмотреть</button>
            </div>
        </div>
    );
};

export default observer(ProductItem);
